  "{param} is not here.": ["Nie ma tu: {param}.", "{param} não está aqui."],
  "There is no wounded ally nearby.": ["W pobliżu nie ma rannego sojusznika.", "Não há aliado ferido por perto."],
  "You cannot cast Heal Friend on yourself.": ["Nie możesz rzucić Uleczenia przyjaciela na siebie.", "Você não pode lançar Curar Amigo em si mesmo."],
  "{name} is too far away.": ["{name} jest za daleko.", "{name} está longe demais."],
  "{name} heals you for {amount} hitpoints.": ["{name} leczy cię o {amount} pkt życia.", "{name} cura você em {amount} pontos de vida."],
  "You fade from sight: monsters can no longer see you.": ["Znikasz z oczu: potwory już cię nie widzą.", "Você some de vista: os monstros não conseguem mais ver você."],
  "Nobody here is wounded.": ["Nikt tu nie jest ranny.", "Ninguém aqui está ferido."],
  "You are not poisoned.": ["Nie ma w tobie trucizny.", "Você não está envenenado."],
  "Say {words} \"Name to find someone.": ["Powiedz {words} \"Imię, aby kogoś znaleźć.", "Diga {words} \"Nome para encontrar alguém."],
  "A player with this name is not online.": ["Gracz o tym imieniu nie jest online.", "Nenhum jogador com esse nome está online."],
  "There is no rope spot here.": ["Nie ma tu miejsca na linę.", "Não há ponto de corda aqui."],
  "Magic lifts you up through the opening.": ["Magia unosi cię przez otwór.", "A magia ergue você pela abertura."],
  "You cannot levitate here.": ["Nie możesz tu lewitować.", "Você não pode levitar aqui."],
  "{n} monster turns on you.": ["{n} potwór rzuca się na ciebie.", "{n} monstro se volta contra você."],
  "{n} monsters turn on you.": ["{n} potwory rzucają się na ciebie.|{n} potwory rzucają się na ciebie.|{n} potworów rzuca się na ciebie.", "{n} monstros se voltam contra você."],
  "No monster answers your challenge.": ["Żaden potwór nie odpowiada na twoje wyzwanie.", "Nenhum monstro responde ao seu desafio."],
  "Say {words} \"creature to take its shape.": ["Powiedz {words} \"stwór, aby przybrać jego postać.", "Diga {words} \"criatura para assumir a forma dela."],
  "There is no creature called \"{param}\".": ["Nie ma stwora o nazwie „{param}”.", "Não existe criatura chamada \"{param}\"."],
  "That creature is too mighty to imitate.": ["Ten stwór jest zbyt potężny, by go naśladować.", "Essa criatura é poderosa demais para imitar."],
  "You need a target. Click an enemy first.": ["Potrzebujesz celu. Najpierw kliknij wroga.", "Você precisa de um alvo. Clique num inimigo primeiro."],
