  "That link is not valid any more.": ["Ten link jest już nieważny.", "Esse link não é mais válido."],
  "You need magic level {level} for the {name}.": ["Potrzebujesz {level}. poziomu magii: {name}.", "Você precisa de nível mágico {level} para: {name}."],
  "You need {skill} level {level} for the {name}.": ["Potrzebujesz poziomu {level} ({skill}): {name}.", "Você precisa de nível {level} em {skill} para: {name}."],
  "The {name} is only for masters of every trade. Still short of {level}: {list}.": ["{name} jest tylko dla mistrzów wszystkich rzemiosł. Brakuje jeszcze poziomu {level}: {list}.", "{name} é só para mestres de todos os ofícios. Ainda falta o nível {level} em: {list}."],
  "The {name} also asks for one fighting art at cape level: a weapon skill or shielding at {level}, or magic level {magic}.": ["{name} wymaga też jednej sztuki walki na poziomie peleryny: umiejętności broni lub obrony tarczą na {level} albo poziomu magii {magic}.", "{name} também exige uma arte de luta no nível de capa: uma habilidade com arma ou defesa com escudo no {level}, ou nível mágico {magic}."],
  "The {name} is only for those who have slain all {n} dungeon bosses ({done}/{all} so far).": ["{name} jest tylko dla tych, którzy pokonali wszystkich bossów lochów ({n}) (na razie {done}/{all}).", "{name} é só para quem derrotou os {n} chefes de masmorra ({done}/{all} até agora)."],
  "The {name} is only for those who have slain all {n} world bosses ({done}/{all} so far).": ["{name} jest tylko dla tych, którzy pokonali wszystkich bossów świata ({n}) (na razie {done}/{all}).", "{name} é só para quem derrotou os {n} chefes mundiais ({done}/{all} até agora)."],
  "The {name} is only sold in {season}.": ["{name} jest sprzedawana tylko {season}.", "{name} só é vendida {season}."],
