  "[A|An] {tree} — click to chop": ["{tree} — kliknij, aby ściąć", "{tree} — clique para cortar"],
  "[A|An] {tree} (woodcutting {n})": ["{tree} (drwalnictwo {n})", "{tree} (lenhador {n})"],
